using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    // starts[l] = r and ends[r] = l for every maximal run [l, r].
    unordered_map<long long, long long> starts, ends;
    long long best = 0;
    string out;
    for (int i = 0; i < n; i++) {
        long long q;
        cin >> q;
        long long left = q, right = q;
        auto e = ends.find(q - 1);
        if (e != ends.end()) {
            left = e->second;
            ends.erase(e);
            starts.erase(left);
        }
        auto s = starts.find(q + 1);
        if (s != starts.end()) {
            right = s->second;
            starts.erase(s);
            ends.erase(right);
        }
        starts[left] = right;
        ends[right] = left;
        best = max(best, right - left + 1);
