import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        HashMap<Long, Long> starts = new HashMap<>(), ends = new HashMap<>();
        long best = 0;
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            long q = nextLong(), left = q, right = q;
            Long l = ends.remove(q - 1);
            if (l != null) {
                left = l;
                starts.remove(left);
            }
            Long r = starts.remove(q + 1);
            if (r != null) {
                right = r;
                ends.remove(right);
            }
            starts.put(left, right);
            ends.put(right, left);
            best = Math.max(best, right - left + 1);
            sb.append(best).append('\n');
        }
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	starts, ends := map[int]int{}, map[int]int{}
	best := 0
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for i := 0; i < n; i++ {
		q := nextInt()
		left, right := q, q
		if l, ok := ends[q-1]; ok {
			left = l
			delete(ends, q-1)
			delete(starts, left)
		}
		if r, ok := starts[q+1]; ok {
			right = r
			delete(starts, q+1)
			delete(ends, right)
		}
		starts[left] = right
		ends[right] = left
		best = max(best, right-left+1)
		w.WriteString(strconv.Itoa(best))
		w.WriteByte('\n')
	}
}
